createCartByStore:
mutation createCartByStore($currency: Currency!, $locale: Locale!, $storeKey: String!, $country: Country!, $taxMode: TaxMode!) {
  createMyCart(
    draft: {currency: $currency, locale: $locale, store: {key: $storeKey}, country: $country, inventoryMode: ReserveOnOrder, shippingMode: Multiple, taxMode: $taxMode}
  ) {
    id
    version
