  }
}

createCheckout:
mutation createCheckout($variantId: String, $location: String, $attributes: [StorefrontCreateCheckoutAttributesElementTypeInput!], $recaptchaToken: String) {
  storefront {
    createCheckout(
      variantId: $variantId
      location: $location
      attributes: $attributes
      recaptchaToken: $recaptchaToken
    ) {
      success
      errors {
        message
        code
        ... on InvalidRecordError {
          model {
            apiIdentifier
            __typename
          }
          validationErrors {
            message
            apiIdentifier
            __typename
          }
          __typename
        }
        __typename
      }
      result
      __typename
    }
    __typename
  }
}

