    billingAddress: {countryId: $countryId, regionId: $regionId, regionCode: $regionCode, region: $region, street: [$street1, $street2], telephone: $telephone, postcode: $postcode, city: $city, firstname: $firstname, lastname: $lastname, saveInAddressBook: 0}
    paymentMethod: {method: "braintree", additional_data: {paypal_pay_id: "null", authorization_id: "null", invoice_number: "null", platform: "Desktop web", version: "1.0", appVersion: "1.0", userId: $userId}}
